/**
*@filedemuxing,decoding,filtering,encodingandmuxingAPIusageexample
*@exampletranscode.c
*
*Convertinputtooutputfile,applyingsomehard-codedfilter-graphonboth
*audioandvideostreams.
*/

#include<libavcodec/avcodec.h>
#include<libavformat/avformat.h>
#include<libavfilter/buffersink.h>
#include<libavfilter/buffersrc.h>
#include<libavutil/channel_layout.h>
#include<libavutil/mem.h>
#include<libavutil/opt.h>
#include<libavutil/pixdesc.h>

staticAVFormatContext*ifmt_ctx;
staticAVFormatContext*ofmt_ctx;
typedefstructFilteringContext{
AVFilterContext*buffersink_ctx;
AVFilterContext*buffersrc_ctx;
AVFilterGraph*filter_graph;

AVPacket*enc_pkt;
AVFrame*filtered_frame;
}FilteringContext;
staticFilteringContext*filter_ctx;

typedefstructStreamContext{
AVCodecContext*dec_ctx;
AVCodecContext*enc_ctx;

AVFrame*dec_frame;
}StreamContext;
staticStreamContext*stream_ctx;

staticintopen_input_file(constchar*filename)
{
intret;
unsignedinti;

ifmt_ctx=NULL;
if((ret=avformat_open_input(&ifmt_ctx,filename,NULL,NULL))<0){
av_log(NULL,AV_LOG_ERROR,"Cannotopeninputfile\n");
returnret;
}

if((ret=avformat_find_stream_info(ifmt_ctx,NULL))<0){
av_log(NULL,AV_LOG_ERROR,"Cannotfindstreaminformation\n");
returnret;
}

stream_ctx=av_calloc(ifmt_ctx->nb_streams,sizeof(*stream_ctx));
if(!stream_ctx)
returnAVERROR(ENOMEM);

for(i=0;i<ifmt_ctx->nb_streams;i++){
AVStream*stream=ifmt_ctx->streams[i];
constAVCodec*dec=avcodec_find_decoder(stream->codecpar->codec_id);
AVCodecContext*codec_ctx;
if(!dec){
av_log(NULL,AV_LOG_ERROR,"Failedtofinddecoderforstream#%u\n",i);
returnAVERROR_DECODER_NOT_FOUND;
}
codec_ctx=avcodec_alloc_context3(dec);
if(!codec_ctx){
av_log(NULL,AV_LOG_ERROR,"Failedtoallocatethedecodercontextforstream#%u\n",i);
returnAVERROR(ENOMEM);
}
ret=avcodec_parameters_to_context(codec_ctx,stream->codecpar);
if(ret<0){
av_log(NULL,AV_LOG_ERROR,"Failedtocopydecoderparameterstoinputdecodercontext"
"forstream#%u\n",i);
returnret;
}

/*Informthedecoderaboutthetimebaseforthepackettimestamps.
*Thisishighlyrecommended,butnotmandatory.*/
codec_ctx->pkt_timebase=stream->time_base;

/*Reencodevideo&audioandremuxsubtitlesetc.*/
if(codec_ctx->codec_type==AVMEDIA_TYPE_VIDEO
||codec_ctx->codec_type==AVMEDIA_TYPE_AUDIO){
if(codec_ctx->codec_type==AVMEDIA_TYPE_VIDEO)
codec_ctx->framerate=av_guess_frame_rate(ifmt_ctx,stream,NULL);
/*Opendecoder*/
ret=avcodec_open2(codec_ctx,dec,NULL);
if(ret<0){
av_log(NULL,AV_LOG_ERROR,"Failedtoopendecoderforstream#%u\n",i);
returnret;
}
}
stream_ctx[i].dec_ctx=codec_ctx;

stream_ctx[i].dec_frame=av_frame_alloc();
if(!stream_ctx[i].dec_frame)
returnAVERROR(ENOMEM);
}

av_dump_format(ifmt_ctx,0,filename,0);
return0;
}

staticintopen_output_file(constchar*filename)
{
AVStream*out_stream;
AVStream*in_stream;
AVCodecContext*dec_ctx,*enc_ctx;
constAVCodec*encoder;
intret;
unsignedinti;

ofmt_ctx=NULL;
avformat_alloc_output_context2(&ofmt_ctx,NULL,NULL,filename);
if(!ofmt_ctx){
av_log(NULL,AV_LOG_ERROR,"Couldnotcreateoutputcontext\n");
returnAVERROR_UNKNOWN;
}


for(i=0;i<ifmt_ctx->nb_streams;i++){
out_stream=avformat_new_stream(ofmt_ctx,NULL);
if(!out_stream){
av_log(NULL,AV_LOG_ERROR,"Failedallocatingoutputstream\n");
returnAVERROR_UNKNOWN;
}

in_stream=ifmt_ctx->streams[i];
dec_ctx=stream_ctx[i].dec_ctx;

if(dec_ctx->codec_type==AVMEDIA_TYPE_VIDEO
||dec_ctx->codec_type==AVMEDIA_TYPE_AUDIO){
/*inthisexample,wechoosetranscodingtosamecodec*/
encoder=avcodec_find_encoder(dec_ctx->codec_id);
if(!encoder){
av_log(NULL,AV_LOG_FATAL,"Necessaryencodernotfound\n");
returnAVERROR_INVALIDDATA;
}
enc_ctx=avcodec_alloc_context3(encoder);
if(!enc_ctx){
av_log(NULL,AV_LOG_FATAL,"Failedtoallocatetheencodercontext\n");
returnAVERROR(ENOMEM);
}

/*Inthisexample,wetranscodetosameproperties(picturesize,
*samplerateetc.).Thesepropertiescanbechangedforoutput
*streamseasilyusingfilters*/
if(dec_ctx->codec_type==AVMEDIA_TYPE_VIDEO){
constenumAVPixelFormat*pix_fmts=NULL;

enc_ctx->height=dec_ctx->height;
enc_ctx->width=dec_ctx->width;
enc_ctx->sample_aspect_ratio=dec_ctx->sample_aspect_ratio;

ret=avcodec_get_supported_config(dec_ctx,NULL,
AV_CODEC_CONFIG_PIX_FORMAT,0,
(constvoid**)&pix_fmts,NULL);

/*takefirstformatfromlistofsupportedformats*/
enc_ctx->pix_fmt=(ret>=0&&pix_fmts)?
pix_fmts[0]:dec_ctx->pix_fmt;

/*videotime_basecanbesettowhateverishandyandsupportedbyencoder*/
enc_ctx->time_base=av_inv_q(dec_ctx->framerate);
}else{
constenumAVSampleFormat*sample_fmts=NULL;

enc_ctx->sample_rate=dec_ctx->sample_rate;
ret=av_channel_layout_copy(&enc_ctx->ch_layout,&dec_ctx->ch_layout);
if(ret<0)
returnret;

ret=avcodec_get_supported_config(dec_ctx,NULL,
AV_CODEC_CONFIG_SAMPLE_FORMAT,0,
(constvoid**)&sample_fmts,NULL);

/*takefirstformatfromlistofsupportedformats*/
enc_ctx->sample_fmt=(ret>=0&&sample_fmts)?
sample_fmts[0]:dec_ctx->sample_fmt;

enc_ctx->time_base=(AVRational){1,enc_ctx->sample_rate};
}

if(ofmt_ctx->oformat->flags&AVFMT_GLOBALHEADER)
enc_ctx->flags|=AV_CODEC_FLAG_GLOBAL_HEADER;

/*Thirdparametercanbeusedtopasssettingstoencoder*/
ret=avcodec_open2(enc_ctx,encoder,NULL);
if(ret<0){
av_log(NULL,AV_LOG_ERROR,"Cannotopen%sencoderforstream#%u\n",encoder->name,i);
returnret;
}
ret=avcodec_parameters_from_context(out_stream->codecpar,enc_ctx);
if(ret<0){
av_log(NULL,AV_LOG_ERROR,"Failedtocopyencoderparameterstooutputstream#%u\n",i);
returnret;
}

out_stream->time_base=enc_ctx->time_base;
stream_ctx[i].enc_ctx=enc_ctx;
}elseif(dec_ctx->codec_type==AVMEDIA_TYPE_UNKNOWN){
av_log(NULL,AV_LOG_FATAL,"Elementarystream#%disofunknowntype,cannotproceed\n",i);
returnAVERROR_INVALIDDATA;
}else{
/*ifthisstreammustberemuxed*/
ret=avcodec_parameters_copy(out_stream->codecpar,in_stream->codecpar);
if(ret<0){
av_log(NULL,AV_LOG_ERROR,"Copyingparametersforstream#%ufailed\n",i);
returnret;
}
out_stream->time_base=in_stream->time_base;
}

}
av_dump_format(ofmt_ctx,0,filename,1);

if(!(ofmt_ctx->oformat->flags&AVFMT_NOFILE)){
ret=avio_open(&ofmt_ctx->pb,filename,AVIO_FLAG_WRITE);
if(ret<0){
av_log(NULL,AV_LOG_ERROR,"Couldnotopenoutputfile'%s'",filename);
returnret;
}
}

/*initmuxer,writeoutputfileheader*/
ret=avformat_write_header(ofmt_ctx,NULL);
if(ret<0){
av_log(NULL,AV_LOG_ERROR,"Erroroccurredwhenopeningoutputfile\n");
returnret;
}

return0;
}

staticintinit_filter(FilteringContext*fctx,AVCodecContext*dec_ctx,
AVCodecContext*enc_ctx,constchar*filter_spec)
{
charargs[512];
intret=0;
constAVFilter*buffersrc=NULL;
constAVFilter*buffersink=NULL;
AVFilterContext*buffersrc_ctx=NULL;
AVFilterContext*buffersink_ctx=NULL;
AVFilterInOut*outputs=avfilter_inout_alloc();
AVFilterInOut*inputs=avfilter_inout_alloc();
AVFilterGraph*filter_graph=avfilter_graph_alloc();

if(!outputs||!inputs||!filter_graph){
ret=AVERROR(ENOMEM);
gotoend;
}

if(dec_ctx->codec_type==AVMEDIA_TYPE_VIDEO){
buffersrc=avfilter_get_by_name("buffer");
buffersink=avfilter_get_by_name("buffersink");
if(!buffersrc||!buffersink){
av_log(NULL,AV_LOG_ERROR,"filteringsourceorsinkelementnotfound\n");
ret=AVERROR_UNKNOWN;
gotoend;
}

snprintf(args,sizeof(args),
"video_size=%dx%d:pix_fmt=%d:time_base=%d/%d:pixel_aspect=%d/%d",
dec_ctx->width,dec_ctx->height,dec_ctx->pix_fmt,
dec_ctx->pkt_timebase.num,dec_ctx->pkt_timebase.den,
dec_ctx->sample_aspect_ratio.num,
dec_ctx->sample_aspect_ratio.den);

ret=avfilter_graph_create_filter(&buffersrc_ctx,buffersrc,"in",
args,NULL,filter_graph);
if(ret<0){
av_log(NULL,AV_LOG_ERROR,"Cannotcreatebuffersource\n");
gotoend;
}

buffersink_ctx=avfilter_graph_alloc_filter(filter_graph,buffersink,"out");
if(!buffersink_ctx){
av_log(NULL,AV_LOG_ERROR,"Cannotcreatebuffersink\n");
ret=AVERROR(ENOMEM);
gotoend;
}

ret=av_opt_set_bin(buffersink_ctx,"pix_fmts",
(uint8_t*)&enc_ctx->pix_fmt,sizeof(enc_ctx->pix_fmt),
AV_OPT_SEARCH_CHILDREN);
if(ret<0){
av_log(NULL,AV_LOG_ERROR,"Cannotsetoutputpixelformat\n");
gotoend;
}

ret=avfilter_init_dict(buffersink_ctx,NULL);
if(ret<0){
av_log(NULL,AV_LOG_ERROR,"Cannotinitializebuffersink\n");
gotoend;
}
}elseif(dec_ctx->codec_type==AVMEDIA_TYPE_AUDIO){
charbuf[64];
buffersrc=avfilter_get_by_name("abuffer");
buffersink=avfilter_get_by_name("abuffersink");
if(!buffersrc||!buffersink){
av_log(NULL,AV_LOG_ERROR,"filteringsourceorsinkelementnotfound\n");
ret=AVERROR_UNKNOWN;
gotoend;
}

if(dec_ctx->ch_layout.order==AV_CHANNEL_ORDER_UNSPEC)
av_channel_layout_default(&dec_ctx->ch_layout,dec_ctx->ch_layout.nb_channels);
av_channel_layout_describe(&dec_ctx->ch_layout,buf,sizeof(buf));
snprintf(args,sizeof(args),
"time_base=%d/%d:sample_rate=%d:sample_fmt=%s:channel_layout=%s",
dec_ctx->pkt_timebase.num,dec_ctx->pkt_timebase.den,dec_ctx->sample_rate,
av_get_sample_fmt_name(dec_ctx->sample_fmt),
buf);
ret=avfilter_graph_create_filter(&buffersrc_ctx,buffersrc,"in",
args,NULL,filter_graph);
if(ret<0){
av_log(NULL,AV_LOG_ERROR,"Cannotcreateaudiobuffersource\n");
gotoend;
}

buffersink_ctx=avfilter_graph_alloc_filter(filter_graph,buffersink,"out");
if(!buffersink_ctx){
av_log(NULL,AV_LOG_ERROR,"Cannotcreateaudiobuffersink\n");
ret=AVERROR(ENOMEM);
gotoend;
}

ret=av_opt_set_bin(buffersink_ctx,"sample_fmts",
(uint8_t*)&enc_ctx->sample_fmt,sizeof(enc_ctx->sample_fmt),
AV_OPT_SEARCH_CHILDREN);
if(ret<0){
av_log(NULL,AV_LOG_ERROR,"Cannotsetoutputsampleformat\n");
gotoend;
}

av_channel_layout_describe(&enc_ctx->ch_layout,buf,sizeof(buf));
ret=av_opt_set(buffersink_ctx,"ch_layouts",
buf,AV_OPT_SEARCH_CHILDREN);
if(ret<0){
av_log(NULL,AV_LOG_ERROR,"Cannotsetoutputchannellayout\n");
gotoend;
}

ret=av_opt_set_bin(buffersink_ctx,"sample_rates",
(uint8_t*)&enc_ctx->sample_rate,sizeof(enc_ctx->sample_rate),
AV_OPT_SEARCH_CHILDREN);
if(ret<0){
av_log(NULL,AV_LOG_ERROR,"Cannotsetoutputsamplerate\n");
gotoend;
}

if(enc_ctx->frame_size>0)
av_buffersink_set_frame_size(buffersink_ctx,enc_ctx->frame_size);

ret=avfilter_init_dict(buffersink_ctx,NULL);
if(ret<0){
av_log(NULL,AV_LOG_ERROR,"Cannotinitializeaudiobuffersink\n");
gotoend;
}
}else{
ret=AVERROR_UNKNOWN;
gotoend;
}

/*Endpointsforthefiltergraph.*/
outputs->name=av_strdup("in");
outputs->filter_ctx=buffersrc_ctx;
outputs->pad_idx=0;
outputs->next=NULL;

inputs->name=av_strdup("out");
inputs->filter_ctx=buffersink_ctx;
inputs->pad_idx=0;
inputs->next=NULL;

if(!outputs->name||!inputs->name){
ret=AVERROR(ENOMEM);
gotoend;
}

if((ret=avfilter_graph_parse_ptr(filter_graph,filter_spec,
&inputs,&outputs,NULL))<0)
gotoend;

if((ret=avfilter_graph_config(filter_graph,NULL))<0)
gotoend;

/*FillFilteringContext*/
fctx->buffersrc_ctx=buffersrc_ctx;
fctx->buffersink_ctx=buffersink_ctx;
fctx->filter_graph=filter_graph;

end:
avfilter_inout_free(&inputs);
avfilter_inout_free(&outputs);

returnret;
}

staticintinit_filters(void)
{
constchar*filter_spec;
unsignedinti;
intret;
filter_ctx=av_malloc_array(ifmt_ctx->nb_streams,sizeof(*filter_ctx));
if(!filter_ctx)
returnAVERROR(ENOMEM);

for(i=0;i<ifmt_ctx->nb_streams;i++){
filter_ctx[i].buffersrc_ctx=NULL;
filter_ctx[i].buffersink_ctx=NULL;
filter_ctx[i].filter_graph=NULL;
if(!(ifmt_ctx->streams[i]->codecpar->codec_type==AVMEDIA_TYPE_AUDIO
||ifmt_ctx->streams[i]->codecpar->codec_type==AVMEDIA_TYPE_VIDEO))
continue;


if(ifmt_ctx->streams[i]->codecpar->codec_type==AVMEDIA_TYPE_VIDEO)
filter_spec="null";/*passthrough(dummy)filterforvideo*/
else
filter_spec="anull";/*passthrough(dummy)filterforaudio*/
ret=init_filter(&filter_ctx[i],stream_ctx[i].dec_ctx,
stream_ctx[i].enc_ctx,filter_spec);
if(ret)
returnret;

filter_ctx[i].enc_pkt=av_packet_alloc();
if(!filter_ctx[i].enc_pkt)
returnAVERROR(ENOMEM);

filter_ctx[i].filtered_frame=av_frame_alloc();
if(!filter_ctx[i].filtered_frame)
returnAVERROR(ENOMEM);
}
return0;
}

staticintencode_write_frame(unsignedintstream_index,intflush)
{
StreamContext*stream=&stream_ctx[stream_index];
FilteringContext*filter=&filter_ctx[stream_index];
AVFrame*filt_frame=flush?NULL:filter->filtered_frame;
AVPacket*enc_pkt=filter->enc_pkt;
intret;

av_log(NULL,AV_LOG_INFO,"Encodingframe\n");
/*encodefilteredframe*/
av_packet_unref(enc_pkt);

if(filt_frame&&filt_frame->pts!=AV_NOPTS_VALUE)
filt_frame->pts=av_rescale_q(filt_frame->pts,filt_frame->time_base,
stream->enc_ctx->time_base);

ret=avcodec_send_frame(stream->enc_ctx,filt_frame);

if(ret<0)
returnret;

while(ret>=0){
ret=avcodec_receive_packet(stream->enc_ctx,enc_pkt);

if(ret==AVERROR(EAGAIN)||ret==AVERROR_EOF)
return0;

/*preparepacketformuxing*/
enc_pkt->stream_index=stream_index;
av_packet_rescale_ts(enc_pkt,
stream->enc_ctx->time_base,
ofmt_ctx->streams[stream_index]->time_base);

av_log(NULL,AV_LOG_DEBUG,"Muxingframe\n");
/*muxencodedframe*/
ret=av_interleaved_write_frame(ofmt_ctx,enc_pkt);
}

returnret;
}

staticintfilter_encode_write_frame(AVFrame*frame,unsignedintstream_index)
{
FilteringContext*filter=&filter_ctx[stream_index];
intret;

av_log(NULL,AV_LOG_INFO,"Pushingdecodedframetofilters\n");
/*pushthedecodedframeintothefiltergraph*/
ret=av_buffersrc_add_frame_flags(filter->buffersrc_ctx,
frame,0);
if(ret<0){
av_log(NULL,AV_LOG_ERROR,"Errorwhilefeedingthefiltergraph\n");
returnret;
}

/*pullfilteredframesfromthefiltergraph*/
while(1){
av_log(NULL,AV_LOG_INFO,"Pullingfilteredframefromfilters\n");
ret=av_buffersink_get_frame(filter->buffersink_ctx,
filter->filtered_frame);
if(ret<0){
/*ifnomoreframesforoutput-returnsAVERROR(EAGAIN)
*ifflushedandnomoreframesforoutput-returnsAVERROR_EOF
*rewriteretcodeto0toshowitasnormalprocedurecompletion
*/
if(ret==AVERROR(EAGAIN)||ret==AVERROR_EOF)
ret=0;
break;
}

filter->filtered_frame->time_base=av_buffersink_get_time_base(filter->buffersink_ctx);;
filter->filtered_frame->pict_type=AV_PICTURE_TYPE_NONE;
ret=encode_write_frame(stream_index,0);
av_frame_unref(filter->filtered_frame);
if(ret<0)
break;
}

returnret;
}

staticintflush_encoder(unsignedintstream_index)
{
if(!(stream_ctx[stream_index].enc_ctx->codec->capabilities&
AV_CODEC_CAP_DELAY))
return0;

av_log(NULL,AV_LOG_INFO,"Flushingstream#%uencoder\n",stream_index);
returnencode_write_frame(stream_index,1);
}

intmain(intargc,char**argv)
{
intret;
AVPacket*packet=NULL;
unsignedintstream_index;
unsignedinti;

if(argc!=3){
av_log(NULL,AV_LOG_ERROR,"Usage:%s<inputfile><outputfile>\n",argv[0]);
return1;
}

if((ret=open_input_file(argv[1]))<0)
gotoend;
if((ret=open_output_file(argv[2]))<0)
gotoend;
if((ret=init_filters())<0)
gotoend;
if(!(packet=av_packet_alloc()))
gotoend;

/*readallpackets*/
while(1){
if((ret=av_read_frame(ifmt_ctx,packet))<0)
break;
stream_index=packet->stream_index;
av_log(NULL,AV_LOG_DEBUG,"Demuxergaveframeofstream_index%u\n",
stream_index);

if(filter_ctx[stream_index].filter_graph){
StreamContext*stream=&stream_ctx[stream_index];

av_log(NULL,AV_LOG_DEBUG,"Goingtoreencode&filtertheframe\n");

ret=avcodec_send_packet(stream->dec_ctx,packet);
if(ret<0){
av_log(NULL,AV_LOG_ERROR,"Decodingfailed\n");
break;
}

while(ret>=0){
ret=avcodec_receive_frame(stream->dec_ctx,stream->dec_frame);
if(ret==AVERROR_EOF||ret==AVERROR(EAGAIN))
break;
elseif(ret<0)
gotoend;

stream->dec_frame->pts=stream->dec_frame->best_effort_timestamp;
ret=filter_encode_write_frame(stream->dec_frame,stream_index);
if(ret<0)
gotoend;
}
}else{
/*remuxthisframewithoutreencoding*/
av_packet_rescale_ts(packet,
ifmt_ctx->streams[stream_index]->time_base,
ofmt_ctx->streams[stream_index]->time_base);

ret=av_interleaved_write_frame(ofmt_ctx,packet);
if(ret<0)
gotoend;
}
av_packet_unref(packet);
}

/*flushdecoders,filtersandencoders*/
for(i=0;i<ifmt_ctx->nb_streams;i++){
StreamContext*stream;

if(!filter_ctx[i].filter_graph)
continue;

stream=&stream_ctx[i];

av_log(NULL,AV_LOG_INFO,"Flushingstream%udecoder\n",i);

/*flushdecoder*/
ret=avcodec_send_packet(stream->dec_ctx,NULL);
if(ret<0){
av_log(NULL,AV_LOG_ERROR,"Flushingdecodingfailed\n");
gotoend;
}

while(ret>=0){
ret=avcodec_receive_frame(stream->dec_ctx,stream->dec_frame);
if(ret==AVERROR_EOF)
break;
elseif(ret<0)
gotoend;

stream->dec_frame->pts=stream->dec_frame->best_effort_timestamp;
ret=filter_encode_write_frame(stream->dec_frame,i);
if(ret<0)
gotoend;
}

/*flushfilter*/
ret=filter_encode_write_frame(NULL,i);
if(ret<0){
av_log(NULL,AV_LOG_ERROR,"Flushingfilterfailed\n");
gotoend;
}

/*flushencoder*/
ret=flush_encoder(i);
if(ret<0){
av_log(NULL,AV_LOG_ERROR,"Flushingencoderfailed\n");
gotoend;
}
}

av_write_trailer(ofmt_ctx);
end:
av_packet_free(&packet);
for(i=0;i<ifmt_ctx->nb_streams;i++){
avcodec_free_context(&stream_ctx[i].dec_ctx);
if(ofmt_ctx&&ofmt_ctx->nb_streams>i&&ofmt_ctx->streams[i]&&stream_ctx[i].enc_ctx)
avcodec_free_context(&stream_ctx[i].enc_ctx);
if(filter_ctx&&filter_ctx[i].filter_graph){
avfilter_graph_free(&filter_ctx[i].filter_graph);
av_packet_free(&filter_ctx[i].enc_pkt);
av_frame_free(&filter_ctx[i].filtered_frame);
}

av_frame_free(&stream_ctx[i].dec_frame);
}
av_free(filter_ctx);
av_free(stream_ctx);
avformat_close_input(&ifmt_ctx);
if(ofmt_ctx&&!(ofmt_ctx->oformat->flags&AVFMT_NOFILE))
avio_closep(&ofmt_ctx->pb);
avformat_free_context(ofmt_ctx);

if(ret<0)
av_log(NULL,AV_LOG_ERROR,"Erroroccurred:%s\n",av_err2str(ret));

returnret?1:0;
}
